-- Canonical Egyptian-market category catalog for Silsila; images are SVG illustrations stored as bytea.
-- The seed is guarded so applying it after an already seeded database is a no-op.
BEGIN;
CREATE TEMP TABLE _silsila_egypt_category_seed(category_code text PRIMARY KEY,activity_code text NOT NULL,category_name text NOT NULL,category_name_en text NOT NULL,parent_code text,level_no integer NOT NULL,show_in_app boolean NOT NULL,is_active boolean NOT NULL) ON COMMIT DROP;
DO $seed$
DECLARE s record; parent_uuid uuid; cat_color text; svg_text text;
BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_item_categories WHERE company_id='47278c99-7743-4dd4-9ce6-d11f28e02504'::uuid AND category_code='ACT001M01') THEN
  RAISE NOTICE 'Catalog already seeded; no changes made.';
 ELSE
  CREATE TABLE IF NOT EXISTS public.erp_item_categories_archive_20261028 (LIKE public.erp_item_categories INCLUDING ALL);
  CREATE TABLE IF NOT EXISTS public.erp_item_category_assignments_backup_20261028 AS SELECT i.id AS item_id,c.category_name,c.category_code,c.activity_code,c.company_id FROM public.erp_items i JOIN public.erp_item_categories c ON c.id=i.category_id WITH NO DATA;
  UPDATE public.erp_items SET category_id=NULL WHERE category_id IS NOT NULL;
  DELETE FROM public.erp_item_categories;
  FOR s IN SELECT * FROM _silsila_egypt_category_seed ORDER BY level_no,activity_code,category_code LOOP
   parent_uuid:=NULL;
   IF s.parent_code IS NOT NULL THEN SELECT id INTO parent_uuid FROM public.erp_item_categories WHERE company_id='47278c99-7743-4dd4-9ce6-d11f28e02504'::uuid AND activity_code=s.activity_code AND category_code=s.parent_code; IF parent_uuid IS NULL THEN RAISE EXCEPTION 'Missing category parent %',s.parent_code; END IF; END IF;
   cat_color:=CASE s.activity_code WHEN 'ACT001' THEN '#3E007D' WHEN 'ACT002' THEN '#B76B00' WHEN 'ACT003' THEN '#C0268C' WHEN 'ACT004' THEN '#1769AA' WHEN 'ACT005' THEN '#374151' WHEN 'ACT006' THEN '#0F766E' WHEN 'ACT007' THEN '#8B5E34' WHEN 'ACT008' THEN '#D97706' WHEN 'ACT009' THEN '#2563EB' WHEN 'ACT010' THEN '#0D9488' WHEN 'ACT011' THEN '#DB2777' WHEN 'ACT012' THEN '#15803D' WHEN 'ACT013' THEN '#475569' WHEN 'ACT014' THEN '#9333EA' WHEN 'ACT015' THEN '#0891B2' WHEN 'ACT016' THEN '#0284C7' WHEN 'ACT017' THEN '#A16207' WHEN 'ACT018' THEN '#0F766E' WHEN 'ACT019' THEN '#64748B' ELSE '#7C3AED' END;
   IF s.level_no=0 THEN svg_text:='<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128"><rect width="128" height="128" rx="18" fill="#FAF8FC"/><rect x="27" y="25" width="74" height="58" rx="10" fill="white" stroke="'||cat_color||'" stroke-width="5"/><path d="M27 41h74" stroke="'||cat_color||'" stroke-width="5"/>';
   ELSIF s.level_no=1 THEN svg_text:='<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128"><rect width="128" height="128" rx="18" fill="#FAF8FC"/><path d="M64 19 101 40v43L64 104 27 83V40Z" fill="white" stroke="'||cat_color||'" stroke-width="5" stroke-linejoin="round"/><path d="M27 40 64 62 101 40M64 62v42" fill="none" stroke="'||cat_color||'" stroke-width="4"/>';
   ELSE svg_text:='<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128"><rect width="128" height="128" rx="18" fill="#FAF8FC"/><circle cx="64" cy="61" r="39" fill="white" stroke="'||cat_color||'" stroke-width="5"/><path d="M64 28v66M31 61h66M41 38l46 46M87 38 41 84" stroke="'||cat_color||'" stroke-width="4" stroke-linecap="round"/>'; END IF;
   svg_text:=svg_text||'<rect x="43" y="103" width="42" height="17" rx="8" fill="'||cat_color||'"/><text x="64" y="115" font-family="Arial,sans-serif" font-size="10" font-weight="700" text-anchor="middle" fill="white">'||right(s.category_code,2)||'</text></svg>';
  END LOOP;
  UPDATE public.erp_items i SET category_id=n.id
  FROM public.erp_item_category_assignments_backup_20261028 b
  JOIN public.erp_item_categories n ON n.company_id=b.company_id AND n.category_code=CASE b.category_code
WHEN 'BABY-CARE' THEN 'ACT001T110101'
WHEN 'BISCUIT-LAMBADA' THEN 'ACT001T060102'
WHEN 'BISCUIT-WAFER' THEN 'ACT001T060102'
WHEN 'CHEESE-RHODES' THEN 'ACT001T050202'
WHEN 'CHEESE-TETRA' THEN 'ACT001T050202'
WHEN 'FOOD-BAKERY' THEN 'ACT001T060101'
WHEN 'FOOD-BAKING' THEN 'ACT001T060201'
WHEN 'FOOD-BISCUITS' THEN 'ACT001T060101'
WHEN 'FOOD-CANDY' THEN 'ACT001T060301'
WHEN 'FOOD-CANNED' THEN 'ACT001T030301'
WHEN 'FOOD-CHEESE' THEN 'ACT001T050202'
WHEN 'FOOD-CHOCOLATE' THEN 'ACT001T060302'
WHEN 'FOOD-DAIRY' THEN 'ACT001T050101'
WHEN 'FOOD-DATES' THEN 'ACT001T080101'
WHEN 'FOOD-FLOUR-SUGAR' THEN 'ACT001T060202'
WHEN 'FOOD-FROZEN' THEN 'ACT001T070301'
WHEN 'FOOD-GHEE' THEN 'ACT001T020202'
WHEN 'FOOD-HOT-DRINKS' THEN 'ACT001T030201'
WHEN 'FOOD-JAMS' THEN 'ACT001T100201'
WHEN 'FOOD-JUICES' THEN 'ACT001T030101'
WHEN 'FOOD-JUICES-TETRA' THEN 'ACT001T030101'
WHEN 'FOOD-LEGUMES' THEN 'ACT001T010201'
WHEN 'FOOD-NUTRITION' THEN 'ACT001T100101'
WHEN 'FOOD-NUTS' THEN 'ACT001T080202'
WHEN 'FOOD-OILS' THEN 'ACT001T020101'
WHEN 'FOOD-PASTA' THEN 'ACT001T010102'
WHEN 'FOOD-PICKLES' THEN 'ACT001T090202'
WHEN 'FOOD-RICE' THEN 'ACT001T010101'
WHEN 'FOOD-SAUCE' THEN 'ACT001T090301'
WHEN 'FOOD-SNACKS' THEN 'ACT001T040301'
WHEN 'FOOD-SOFT-DRINKS' THEN 'ACT001T030102'
WHEN 'FOOD-SPICES' THEN 'ACT001T090101'
WHEN 'HOME-AIR' THEN 'ACT001T120102'
WHEN 'HOME-CLEANING' THEN 'ACT001T120101'
WHEN 'HOME-KITCHEN' THEN 'ACT014T040101'
WHEN 'HOME-LAUNDRY' THEN 'ACT001T120202'
WHEN 'HOME-PAPER' THEN 'ACT001T120302'
WHEN 'HOME-TOOLS' THEN 'ACT001T120301'
WHEN 'JUICE-BETTY' THEN 'ACT001T030102'
WHEN 'JUICE-JUHAINA' THEN 'ACT001T030101'
WHEN 'PERSONAL-CARE' THEN 'ACT001T110201'
WHEN 'PET-FOOD' THEN 'ACT017T010101'
    ELSE 'ACT001T010101' END
  WHERE i.id=b.item_id;
  ALTER TABLE public.erp_item_categories_archive_20261028 ENABLE ROW LEVEL SECURITY;
  ALTER TABLE public.erp_item_category_assignments_backup_20261028 ENABLE ROW LEVEL SECURITY;
  REVOKE ALL ON public.erp_item_categories_archive_20261028 FROM anon,authenticated;
  REVOKE ALL ON public.erp_item_category_assignments_backup_20261028 FROM anon,authenticated;
 END IF;
END $seed$;
COMMIT;